      CONTINUE;
    ELSEIF prop = 'birth' THEN
      -- handle must birth property
      must_count := must_count + 1;
      -- .'$PersonId'.birth
      res := JSONB_TYPEOF(pval) = 'string' AND jm_is_valid_date(JSON_VALUE(pval, '$' RETURNING TEXT), NULL, NULL);
      IF NOT res THEN
